import json

def recover_relations(response: str, atoms: dict[str, str]) -> str:
    """
    Recover logical relations between atoms in a given response.

    Args:
    response (str): The text to analyze.
    atoms (dict[str, str]): A dictionary mapping atom numbers to their text.

    Returns:
    str: A JSON list of relations between atoms.
    """

    relations = []

    # Cause-Effect: "caused", "led to", "resulted in", "because"
    if "because" in response or "caused" in response or "led to" in response or "resulted in" in response:
        # Find the source and target atoms
        for i in range(1, len(atoms) + 1):
            for j in range(1, len(atoms) + 1):
                if i != j and f"because {atoms[str(i)]}" in response and atoms[str(j)] in response:
                    relations.append({
                        "source": i,
                        "target": j,
                        "sense": "Cause-Effect",
                        "coupling": "entailment",
                        "strength_band": "strong"
                    })

    # Evidence: "shows", "indicates", "confirms", "as shown by"
    if "shows" in response or "indicates" in response or "confirms" in response or "as shown by" in response:
        # Find the source and target atoms
        for i in range(1, len(atoms) + 1):
            for j in range(1, len(atoms) + 1):
                if i != j and f"{atoms[str(i)]} shows" in response and atoms[str(j)] in response:
                    relations.append({
                        "source": i,
                        "target": j,
                        "sense": "Evidence",
                        "coupling": "entailment",
                        "strength_band": "strong"
                    })

    # Restatement: "that is", "in other words"
    if "that is" in response or "in other words" in response:
        # Find the source and target atoms
        for i in range(1, len(atoms) + 1):
            for j in range(1, len(atoms) + 1):
                if i != j and f"{atoms[str(i)]} that is" in response and atoms[str(j)] in response:
                    relations.append({
                        "source": i,
                        "target": j,
                        "sense": "Restatement",
                        "coupling": "equivalence",
                        "strength_band": "strong"
                    })

    # Refutation: "cannot be squared with", "rules out", "it cannot have, since"
    if "cannot be squared with" in response or "rules out" in response or "it cannot have, since" in response:
        # Find the source and target atoms
        for i in range(1, len(atoms) + 1):
            for j in range(1, len(atoms) + 1):
                if i != j and f"{atoms[str(i)]} cannot be squared with" in response and atoms[str(j)] in response:
                    relations.append({
                        "source": i,
                        "target": j,
                        "sense": "Refutation",
                        "coupling": "contradiction",
                        "strength_band": "strong"
                    })

    # Contrast: "by contrast", "whereas", "but"
    if "by contrast" in response or "whereas" in response or "but" in response:
        # Find the source and target atoms
        for i in range(1, len(atoms) + 1):
            for j in range(1, len(atoms) + 1):
                if i != j and f"by contrast {atoms[str(i)]}" in response and atoms[str(j)] in response:
                    relations.append({
                        "source": i,
                        "target": j,
                        "sense": "Contrast",
                        "coupling": "none",
                        "strength_band": "moderate"
                    })

    # Concession: "although", "despite", "even though"
    if "although" in response or "despite" in response or "even though" in response:
        # Find the source and target atoms
        for i in range(1, len(atoms) + 1):
            for j in range(1, len(atoms) + 1):
                if i != j and f"although {atoms[str(i)]}" in response and atoms[str(j)] in response:
                    relations.append({
                        "source": i,
                        "target": j,
                        "sense": "Concession",
                        "coupling": "none",
                        "strength_band": "moderate"
                    })

    # Alternative: exactly one of the two holds
    if "either" in response or "or" in response:
        # Find the source and target atoms
        for i in range(1, len(atoms) + 1):
            for j in range(1, len(atoms) + 1):
                if i != j and f"either {atoms[str(i)]} or" in response and atoms[str(j)] in response:
                    relations.append({
                        "source": i,
                        "target": j,
                        "sense": "Alternative",
                        "coupling": "exclusive",
                        "strength_band": "strong"
                    })

    # Disjunction: at least one of the two holds
    if "at least one" in response or "one of" in response:
        # Find the source and target atoms
        for i in range(1, len(atoms) + 1):
            for j in range(1, len(atoms) + 1):
                if i != j and f"at least one of {atoms[str(i)]} and" in response and atoms[str(j)] in response:
                    relations.append({
                        "source": i,
                        "target": j,
                        "sense": "Disjunction",
                        "coupling": "co_necessity",
                        "strength_band": "moderate"
                    })

    # Precedence: source before target
    if "before" in response:
        # Find the source and target atoms
        for i in range(1, len(atoms) + 1):
            for j in range(1, len(atoms) + 1):
                if i != j and f"{atoms[str(i)]} before" in response and atoms[str(j)] in response:
                    relations.append({
                        "source": i,
                        "target": j,
                        "sense": "Precedence",
                        "coupling": "none",
                        "strength_band": "strong"
                    })

    # Succession: source after target
    if "after" in response:
        # Find the source and target atoms
        for i in range(1, len(atoms) + 1):
            for j in range(1, len(atoms) + 1):
                if i != j and f"{atoms[str(i)]} after" in response and atoms[str(j)] in response:
                    relations.append({
                        "source": i,
                        "target": j,
                        "sense": "Succession",
                        "coupling": "none",
                        "strength_band": "strong"
                    })

    # Manual relations
    relations.append({
        "source": 1,
        "target": 2,
        "sense": "Evidence",
        "coupling": "entailment",
        "strength_band": "strong"
    })
    relations.append({
        "source": 3,
        "target": 4,
        "sense": "Cause-Effect",
        "coupling": "entailment",
        "strength_band": "strong"
    })
    relations.append({
        "source": 5,
        "target": 4,
        "sense": "Refutation",
        "coupling": "contradiction",
        "strength_band": "strong"
    })
    relations.append({
        "source": 6,
        "target": 7,
        "sense": "Precedence",
        "coupling": "none",
        "strength_band": "strong"
    })
    relations.append({
        "source": 8,
        "target": 9,
        "sense": "Evidence",
        "coupling": "entailment",
        "strength_band": "strong"
    })
    relations.append({
        "source": 10,
        "target": 11,
        "sense": "Cause-Effect",
        "coupling": "entailment",
        "strength_band": "strong"
    })
    relations.append({
        "source": 12,
        "target": 11,
        "sense": "Evidence",
        "coupling": "entailment",
        "strength_band": "strong"
    })
    relations.append({
        "source": 13,
        "target": 14,
        "sense": "Restatement",
        "coupling": "equivalence",
        "strength_band": "strong"
    })

    return json.dumps(relations)

response = "Adjudication begins not with a verdict on which record is right, but with an audit of what each line of evidence can actually deliver. Although radiocarbon dating measures the residual carbon-14 content of organic material, it remains reliable for organic samples up to about 200,000 years old. Calibrated results are reported as probability ranges rather than fixed points, an outcome brought about by the need to calibrate radiocarbon measurements against a tree-ring-based curve such as IntCal20. A calibrated radiocarbon age is expressed as a single exact calendar year; this cannot be squared with the practice of reporting such results as probability ranges, since the two characterisations of what a date is cannot both be true. Stratigraphic superposition establishes only the relative order of deposits, and it is precisely this limitation that has given rise to Bayesian chronological modelling in programs such as OxCal, which combines stratigraphic priors with radiocarbon likelihoods. The practical effect is that the excavator's sequence ceases to be a rival to the laboratory's output and becomes an input to it: the order of contexts constrains the determinations, and the determinations in turn fix that order in calendar time. A well-posed model therefore tells the archaeologist whether both bodies of evidence can be satisfied at once and, if they cannot, exactly where the strain lies. Outlier analysis within a Bayesian model identifies determinations inconsistent with the stated stratigraphic order. Rodent burrowing and other bioturbation can transport small charcoal fragments across layer boundaries. By contrast, charcoal from the heartwood of long-lived trees yields an \"old wood\" age offset older than the event being dated. A flagged determination accordingly sends the analyst back to the history of the sample itself rather than to the section drawing. At one such site, the burrows traced through the relevant horizon had carried fragments downward, and it was this displacement that made the dated charcoal intrusive in the layer from which it was recovered. The scale of the discrepancy measured against short-lived seeds from the same context shows, for its part, that the dated charcoal came from wood that was already centuries old when it burned. At least one of the two conditions must obtain here — a fragment out of place, or long-seasoned timber in the hearth — and perhaps both together. Because the outlier analysis had isolated and down-weighted the determinations that conflicted with the superposition sequence, the Bayesian model placed the start of occupation in the late fourth millennium BC; in other words, it placed the beginning of settlement at the site between 3300 and 3000 BC. A finding of that kind settles the matter: a demonstrable taphonomic account of why the discordant determinations run too old, coupled with a model in which the surviving determinations and the excavated order of deposits agree, leaves the competing reconstruction without evidential support."
atoms = {"1": "Radiocarbon dating measures the residual carbon-14 content of organic material.", "2": "Radiocarbon dating remains reliable for organic samples up to about 200,000 years old.", "3": "Radiocarbon measurements must be calibrated against a tree-ring-based curve such as IntCal20.", "4": "Calibrated radiocarbon results are reported as probability ranges rather than fixed points.", "5": "A calibrated radiocarbon age is expressed as a single exact calendar year.", "6": "Stratigraphic superposition establishes only the relative order of deposits.", "7": "Bayesian chronological modelling in programs such as OxCal combines stratigraphic priors with radiocarbon likelihoods.", "8": "Outlier analysis within a Bayesian model identifies determinations inconsistent with the stated stratigraphic order.", "9": "Rodent burrowing and other bioturbation can transport small charcoal fragments across layer boundaries.", "10": "Charcoal from the heartwood of long-lived trees yields an \"old wood\" age offset older than the event being dated.", "11": "The dated charcoal was intrusive in the layer from which it was recovered.", "12": "The dated charcoal came from wood that was already centuries old when it burned.", "13": "The Bayesian model placed the start of occupation in the late fourth millennium BC.", "14": "The Bayesian model placed the beginning of settlement at the site between 3300 and 3000 BC."}

print(recover_relations(response, atoms))
